    @mark_to_call_base_class_method_with_same_name
    def _prepare_transitions_with_proxy_pc(self):
        """
        Prepare transitions to change states with proxy_pc state.

        :return: transitions with proxy_pc state.
        """
        transitions = {
            Hub.linux: {
                Hub.proxy_pc: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Hub.aashell: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
                Hub.fzhub: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                },
                Hub.rfsw_cli: {
                    "action": [
                        "_execute_command_to_change_state"
                    ]
                }
            },
            Hub.proxy_pc: {
                Hub.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                },
            },
            Hub.aashell: {
                Hub.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Hub.fzhub: {
                Hub.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
            Hub.rfsw_cli: {
                Hub.linux: {
                    "action": [
                        "_execute_command_to_change_state"
                    ],
                }
            },
        }
        return transitions

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_with_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine with proxy_pc state.

        :return: textual prompt for each state with proxy_pc state.
        """
        state_prompts = {
            Hub.linux:
                self._configurations[Hub.connection_hops][Hub.proxy_pc][Hub.linux][
                    "command_params"]["expected_prompt"],
            Hub.aashell:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.aashell][
                    "command_params"]["expected_prompt"],
            Hub.fzhub:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.fzhub][
                    "command_params"]["expected_prompt"],
            Hub.rfsw_cli:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.rfsw_cli][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_prompts_without_proxy_pc(self):
        """
        Prepare textual prompt for each state for State Machine without proxy_pc state.

        :return: textual prompt for each state without proxy_pc state.
        """
        state_prompts = {
            Hub.linux:
                self._configurations[Hub.connection_hops][Hub.unix_local][Hub.linux][
                    "command_params"]["expected_prompt"],
            Hub.aashell:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.aashell][
                    "command_params"]["expected_prompt"],
            Hub.fzhub:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.fzhub][
                    "command_params"]["expected_prompt"],
            Hub.rfsw_cli:
                self._configurations[Hub.connection_hops][Hub.linux][Hub.rfsw_cli][
                    "command_params"]["expected_prompt"],
        }
        return state_prompts

    @mark_to_call_base_class_method_with_same_name
    def _prepare_state_hops_with_proxy_pc(self):
        """
        Prepare non direct transitions for each state for State Machine with proxy_pc state.

        :return: non direct transitions for each state with proxy_pc state.
        """
        state_hops = {
            Hub.not_connected: {
                Hub.linux: Hub.unix_local,
                Hub.aashell: Hub.unix_local,
                Hub.fzhub: Hub.unix_local,
                Hub.rfsw_cli: Hub.unix_local,
            },
            Hub.unix_local: {
                Hub.linux: Hub.proxy_pc,
                Hub.aashell: Hub.proxy_pc,
                Hub.fzhub: Hub.proxy_pc,
                Hub.rfsw_cli: Hub.proxy_pc
            },
            Hub.proxy_pc: {
                Hub.aashell: Hub.linux,
                Hub.fzhub: Hub.linux,
                Hub.rfsw_cli: Hub.linux
            },
            Hub.linux: {
                Hub.not_connected: Hub.proxy_pc,
                Hub.unix_local: Hub.proxy_pc,
                Hub.unix_local_root: Hub.proxy_pc
            },
            Hub.aashell: {
                Hub.unix_local: Hub.linux,
                Hub.proxy_pc: Hub.linux,
                Hub.not_connected: Hub.linux,
                Hub.fzhub: Hub.linux,
                Hub.rfsw_cli: Hub.linux,
                Hub.unix_local_root: Hub.linux
            },
            Hub.fzhub: {
                Hub.unix_local: Hub.linux,
                Hub.proxy_pc: Hub.linux,
                Hub.not_connected: Hub.linux,
                Hub.aashell: Hub.linux,
                Hub.rfsw_cli: Hub.linux,
                Hub.unix_local_root: Hub.linux
            },
            Hub.rfsw_cli: {
                Hub.unix_local: Hub.linux,
                Hub.proxy_pc: Hub.linux,
                Hub.not_connected: Hub.linux,
                Hub.aashell: Hub.linux,
                Hub.fzhub: Hub.linux,
                Hub.unix_local_root: Hub.linux
            },
            Hub.unix_local_root: {
                Hub.linux: Hub.unix_local,
                Hub.aashell: Hub.unix_local,
                Hub.fzhub: Hub.unix_local,
                Hub.rfsw_cli: Hub.unix_local
            }
        }
        return state_hops

    def _get_packages_for_state(self, state, observer):
        """
        Get available packages contain cmds and events for each state.

        :param state: device state.
        :param observer: observer type, available: cmd, events
        :return: available cmds or events for specific device state.
        """
        available = super(Hub, self)._get_packages_for_state(state, observer)

        if not available:
            if state == Hub.linux:
                available = {
                    Hub.cmds: ['moler.cmd.unix', 'ta_moler.cmd.shared.nokiaunix', 'ta_moler.cmd.shared.enblinux', 'ta_moler.cmd.hub.linux'],
                    Hub.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.hub']}
            elif state == Hub.aashell:
                available = {Hub.cmds: ['ta_moler.cmd.shared.aashell', 'ta_moler.cmd.hub.aashell'],
                             Hub.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.hub']}
            elif state == Hub.fzhub:
                available = {Hub.cmds: ['ta_moler.cmd.shared.argon', 'ta_moler.cmd.hub.fzhub'],
                             Hub.events: ['moler.events.shared', 'moler.events.unix', 'ta_moler.events.hub']}
            elif state == Hub.rfsw_cli:
                available = {Hub.cmds: ['ta_moler.cmd.hub.rfswcli'],
                             Hub.events: ['moler.events.shared', 'moler.events.unix']}

            if available:
                return available[observer]

        return available

    def _trim_config_dicts(self, default_sm_configurations, transitions, state_hops):
        default_sm_configurations, transitions, state_hops = super()._trim_config_dicts(default_sm_configurations, transitions, state_hops)
        if Hub.proxy_pc not in default_sm_configurations[Hub.connection_hops]:
            default_sm_configurations[Hub.connection_hops][Hub.unix_local][Hub.linux]["required_command_params"] = ["host", "port"]
            default_sm_configurations[Hub.connection_hops][Hub.linux][Hub.unix_local]["execute_command"] = "exit_telnet"
        return default_sm_configurations, transitions, state_hops
